// i manifesti veri di biodom+ (HAVE YOU CHECKED YOUR PLANTS TODAY? · EACH BREATH IS A CHOICE b+ ·
// EACH BREATH con la foglia), ritagliati dalla foto della campagna. Nel gioco passano dal filtro
// della palette con la grana, come tutto il resto.
const SRC = [
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,",
  "data:image/jpeg;base64,"
];
export const POSTER_IMGS = SRC.map((src) => {
  const im = new Image();
  im.src = src;
  return im;
});
// pronti (decodificati): da chiamare prima di disegnare i luoghi
export const postersReady = Promise.all(POSTER_IMGS.map((im) => (im.decode ? im.decode().catch(() => {}) : Promise.resolve())));
